def write_json(path: Path, payload: object) -> None:
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def validate() -> None:
    assert all(set(r) == set(COLUMNS) for r in MATRIX)
    assert all(r["current_status"] in STATUSES for r in MATRIX)
    assert all(r["priority"] in PRIORITIES for r in MATRIX)
    assert all(r["risk_if_omitted"] in RISKS for r in MATRIX)
    assert len({r["evidence_id"] for r in MATRIX}) == len(MATRIX)
    assert DECISION in {"SPRINT_10.8.2.32_GO", "SPRINT_10.8.2.32_GO_WITH_LIMITATIONS", "SPRINT_10.8.2.32_BLOCKED"}


def main(root: Path | None = None) -> None:
    validate()
    repo = root or Path(__file__).resolve().parents[1]
    out = repo / "audits/q1-experimental-evidence-gap-audit" / VERSION
    out.mkdir(parents=True, exist_ok=True)
    write_json(out / "experimental_evidence_matrix.json", {"schema_version": VERSION, "allowed_statuses": sorted(STATUSES), "rows": MATRIX})
    with (out / "experimental_evidence_matrix.csv").open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=COLUMNS)
        writer.writeheader()
        writer.writerows(MATRIX)
    write_json(out / "q1_contribution_audit.json", {"schema_version": VERSION, "contributions": CONTRIBUTIONS})
    write_json(out / "experimental_roadmap.json", {"schema_version": VERSION, "random_cv_decision": "REJECT ordinary shuffled/random k-fold CV=2..11 for temporally ordered JIT prediction; use blocked or rolling-origin evaluation.", "sprints": ROADMAP})
    write_json(out / "reviewer_traceability.json", reviewer_traceability())
    write_json(out / "research_question_alignment.json", rq_alignment())
    write_json(out / "test_governance.json", test_governance())


